<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { overallSnapshotCoverage, updateCoverageClock } from '../data/snapshot-coverage';
import { displaySettings } from '../data/display-settings';
import { storedSnapshots, refreshSnapshots } from '../data/stored-snapshots';
const emit = defineEmits<{ navigate:[section:string] }>();
function openCoverage() { if (displaySettings.snapshotBanner) emit('navigate',overallSnapshotCoverage.value.tone === 'success' ? 'history' : 'snapshot-coverage'); }
const now = ref(Date.now()); const error = ref(''); const loaded = ref(false); let timer: ReturnType<typeof setInterval>;
onMounted(async () => { timer = setInterval(() => { now.value = Date.now(); updateCoverageClock(); }, 60000); try { await refreshSnapshots(); loaded.value = true; } catch { error.value = 'Snapshot storage could not be checked.'; } });
onUnmounted(() => clearInterval(timer));
const latest = computed(() => [...storedSnapshots.value].filter(snapshot => Number.isFinite(Date.parse(snapshot.createdAt)) && Date.parse(snapshot.createdAt) <= now.value).sort((a,b) => Date.parse(b.createdAt)-Date.parse(a.createdAt))[0]);
watch(storedSnapshots,()=>{now.value=Date.now();},{flush:'sync'});
const recent = computed(() => !!latest.value && now.value - Date.parse(latest.value.createdAt) < 7 * 86400000);
</script>
<template><div class="snapshot-banner" :class="displaySettings.snapshotBanner ? overallSnapshotCoverage.tone : ''" :role="displaySettings.snapshotBanner ? 'button' : 'status'" :tabindex="displaySettings.snapshotBanner ? 0 : undefined" :aria-label="displaySettings.snapshotBanner ? `${overallSnapshotCoverage.label} — View Snapshot Coverage` : undefined" @click="openCoverage" @keydown.enter.prevent="openCoverage" @keydown.space.prevent="openCoverage"><strong v-if="displaySettings.snapshotBanner && latest">{{ overallSnapshotCoverage.label }} · {{ new Date(latest.createdAt).toLocaleString() }}</strong><strong v-else-if="displaySettings.snapshotBanner">{{ error || (loaded ? 'No Snapshots Available — Create A Configuration Snapshot' : 'Checking Saved Snapshots…') }}</strong><span v-if="displaySettings.snapshotBanner && latest">Scope: {{ latest.scope?.label || latest.name }}. {{ overallSnapshotCoverage.covered }} / {{ overallSnapshotCoverage.total }} known configuration items covered by matching snapshots from the last seven days.</span><small v-if="displaySettings.previewMode && displaySettings.inspectionInfo">Preview inventory: 35 routing resources inspected October 11. Cluster data is static; forms create local drafts.</small></div></template>
<style scoped>.snapshot-banner { flex-shrink:0; padding:12px 16px; border-left:3px solid #619bd9; background:var(--box-bg,#202e40); margin:22px 0; font-size:12px; line-height:1.6; }.snapshot-banner[role="button"]{cursor:pointer}.snapshot-banner:focus-visible{outline:2px solid #73b5ff;outline-offset:3px}.snapshot-banner strong,.snapshot-banner span,.snapshot-banner small { display:block; }.snapshot-banner small { font-size:11px; margin-top:4px; }.snapshot-banner.success { border-color:#67c89a; background:#203e37; color:#b5e4cc; }.snapshot-banner.error { border-color:#ed7777; background:#4c282e; color:#ffb3ad; }.snapshot-banner.warning { border-color:#edbb69; background:#443923; color:#f2d59a; }</style>
